CREATE TABLE IF NOT EXISTS _now(entity TEXT NOT NULL, line TEXT NOT NULL, key TEXT NOT NULL, to_key TEXT NOT NULL, arrived INTEGER NOT NULL, axis BLOB NOT NULL, known INTEGER NOT NULL, event TEXT NOT NULL, PRIMARY KEY(entity, line, key, to_key)) WITHOUT ROWID; CREATE INDEX IF NOT EXISTS _now_to ON _now(entity, line, to_key, key); CREATE TRIGGER IF NOT EXISTS now_h AFTER INSERT ON _hearings WHEN new.until IS NULL BEGIN INSERT INTO _now VALUES (new.entity, new.line, new.key, coalesce(new.to_key, ''), new.arrived, new.axis, new.known, new.event) ON CONFLICT(entity, line, key, to_key) DO UPDATE SET arrived = excluded.arrived, axis = excluded.axis, known = excluded.known, event = excluded.event WHERE (excluded.axis, excluded.known, excluded.event) > (_now.axis, _now.known, _now.event); END; CREATE TRIGGER IF NOT EXISTS now_a AFTER INSERT ON _aliases BEGIN INSERT INTO _now SELECT h.entity, h.line, h.key, coalesce(h.to_key, ''), h.arrived, new.axis, new.known, new.alias FROM _hearings h WHERE h.line = new.line AND h.identity = new.identity AND h.until IS NULL ON CONFLICT(entity, line, key, to_key) DO UPDATE SET arrived = excluded.arrived, axis = excluded.axis, known = excluded.known, event = excluded.event WHERE (excluded.axis, excluded.known, excluded.event) > (_now.axis, _now.known, _now.event); END;
